   subroutine ip_states(dist,v,grad,n,ns)
   implicit none
   integer, intent(in) :: n, ns
   real*8,intent(in)  :: dist(n*(n-1)/2)
   real*8,intent(inout)  :: v(ns)
   real*8,intent(inout)  :: grad(ns,n*(n-1)/2)

   real*8 :: rmin, r2, r3
   real*8 :: gap
   real*8 :: rcom
   real*8 :: ip, ionic(3)
   real*8 :: all_e(19)
   real*8 :: low16(ns)

   integer :: idx(1), istate
   integer :: pos, j

   real*8 :: pair_sum, bond_sum, bond_sum_inv
   integer :: nbonds, ibond, jbond
   real*8 :: order 

   ! for computing ground state diatomic energy
   real*8 :: v_diatomic(ns), v2b_diatomic(ns), grad_diatomic(ns)

   ! for gradient 
   real*8 :: g_ip(n*(n-1)/2)
   real*8 :: all_g(19, n*(n-1)/2)
   real*8 :: low16g(ns, n*(n-1)/2)
   real*8 :: drcom_dr(n*(n-1)/2)
   real*8 :: drmin_dr(n*(n-1)/2)
   real*8 :: dpair_drk, dbond_drk, S
   real*8 :: s1, s2, ds1_drmin, ds2_drmin, dip_drmin
   real*8 :: Eh, a1, a2, b1, b2, r1ip, r2ip, ang2bohr
   real*8 :: tmp

   Eh=27.211608d0 
   ang2bohr=1.0d0/0.529177249d0
   a1=9.105969581048d0
   a2=9.02188625911906d0
   b1=17.288085933831d0
   b2=44.8646954407384d0
   r1ip=0.795647491227032d0
   r2ip=1.06219636583541d0
   order=4.d0
   nbonds=int(n*(n-1)/2)

   ! rcom
   pair_sum=0.d0
   do ibond=1,nbonds
   do jbond=ibond+1, nbonds
     pair_sum=pair_sum+(dist(ibond)+dist(jbond))**order
   enddo
   enddo

   bond_sum=0.d0
   do ibond=1,nbonds
     bond_sum=bond_sum+dist(ibond)**order
   enddo

   rcom=pair_sum**(1.d0/order)-bond_sum**(1.d0/order)

   ! computing r_min 
   bond_sum_inv=0.d0
   do ibond=1,nbonds
     bond_sum_inv=bond_sum_inv+dist(ibond)**(-1.d0*order)
   enddo
    rmin=bond_sum_inv**(-1.0/order)

   ! for computing ground state diatomic energy
   v2b_diatomic=0.d0
   grad_diatomic=0.d0
   call ev2gm2(rmin,v_diatomic,grad_diatomic,4,1)
   v2b_diatomic=v2b_diatomic+v_diatomic/23.061d0

   ! IP(rmin)
   ip=a1/(1.d0+exp(-b1*(rmin-r1ip)))+a2/(1.d0+exp(-b2*(rmin-r2ip)))
   ip=ip+v2b_diatomic(1)

   ! W_IP
   ionic(1)=27.211608*((2.0/rcom)**8)-27.211608/(rcom/0.529177)+ip-1.46
   gap=0.117
   ionic(2)=ionic(1)+gap
   ionic(3)=ionic(2)

   ! gradients: drcom/dr_k and drmin/dr_k
   do ibond=1,nbonds
      dpair_drk=0.d0
      do jbond=1,nbonds
         if (jbond.ne.ibond) then
            dpair_drk=dpair_drk+order*(dist(ibond)+dist(jbond))**(order-1.0)
         endif
      enddo
      dbond_drk=order*dist(ibond)**(order-1.0)

      ! drcom/dr_k = (1/4) pair_sum^{-3/4} * dpair_drk - (1/4) bond_sum^{-3/4} * dbond_drk
      drcom_dr(ibond)=(1.d0/order)*pair_sum**(-(order-1.0)/order)*dpair_drk  &
                       -(1.d0/order)*bond_sum**(-(order-1.0)/order)*dbond_drk

      ! For rmin = S^{-1/4}, with S = sum r_i^{-4},
      ! dS/dr_k = -4 r_k^{-5}  => drmin/dr_k = -1/4 * S^{-5/4} * (-4 r_k^{-5}) = S^{-5/4} * r_k^{-5} = rmin^5 * r_k^{-5}
      drmin_dr(ibond)=rmin**(order+1.0)*dist(ibond)**(-(order+1.0))
   enddo

   ! d(ip)/drmin
   s1=1.d0/(1.d0+exp(-b1*(rmin-r1ip)))
   s2=1.d0/(1.d0+exp(-b2*(rmin-r2ip)))
   ds1_drmin=b1*s1*(1.d0-s1)
   ds2_drmin=b2*s2*(1.d0-s2)
   dip_drmin=a1*ds1_drmin+a2*ds2_drmin+grad_diatomic(1)/23.061d0

   ! g_ip
   do ibond=1,nbonds
     g_ip(ibond)=(-Eh*2048.d0*rcom**(-9.d0)+Eh*0.529177d0*rcom**(-2.d0))*drcom_dr(ibond)+dip_drmin*drmin_dr(ibond)
   enddo

   ! pack energies and gradients: 16 neutral + 3 ionic
   do istate=1,16
     all_e(istate)=v(istate)
     all_g(istate,:)=grad(istate,:)
   enddo
   all_e(17)=ionic(1)
   all_g(17,:)=g_ip(:)
   all_e(18)=ionic(2)
   all_g(18,:)=g_ip(:)
   all_e(19)=ionic(3)
   all_g(19,:)=g_ip(:)

   ! Select lowest 16 with matched gradients
   do istate=1,16
     pos=1
     do j=2,19
       if (all_e(j)<all_e(pos)) pos=j
     enddo
     low16(istate)=all_e(pos)
     low16g(istate,:)=all_g(pos,:)
     all_e(pos)=huge(1.0d0)
   enddo
 
   v=low16
   grad=low16g

 endsubroutine

 subroutine ev2gm2m(dist,v2b,g2b,imol,igrad,n)

    implicit none

    integer,intent(in) :: imol, igrad
    integer,intent(in) :: n
    double precision,intent(in)  :: dist(int(n*(n-1)/2))
    double precision,intent(out) :: v2b(16), g2b(16,3)
    double precision :: v(16), grad(16)
    double precision :: r
    integer :: i,j

    ! dist should be in Ang
    ! v2b is in kcal/mol
    ! grad2b is in kcal/molAng

    v2b = 0.d0
    g2b = 0.0d0
    do i=1,n*(n-1)/2
      r=dist(i)
      call ev2gm2(r,v,grad,imol,igrad)

      v2b = v2b + v/23.061d0
      if (igrad.eq.1) then
        do j=1,16
          g2b(j,i) = grad(j)/23.061d0
        enddo
      endif
    enddo

  endsubroutine ev2gm2m
    
  subroutine ev2gm2(r,v,grad,imol,igrad) 
          implicit none
    
          integer,intent(in) :: imol, igrad
          double precision,intent(in)  :: r
          double precision,intent(out) :: v(16), grad(16)
          double precision :: alpha,beta,as(0:7)
          double precision :: gam, del
          integer :: i,j,k 
    
          v=0.0d0
          grad=0.0d0
    
          do i=1,16
      if (i.eq.1) then
      as(0) = 	71492.0825
      as(1) = 	-96462.2714
      as(2) = 	124669.5962
      as(3) = 	-117580.8781
      as(4) = 	106349.5143
      as(5) = 	-72387.5754
      as(6) = 	37409.2123
      as(7) = 	-10165.7980
      alpha = 	12.3688
      beta = 	0.7421

       else if ((i.eq.2).or.(i.eq.3).or.(i.eq.4)) then
      ! O2 a 1Del_g
      as(0) = 	15613.5276
      as(1) = 	-2404.4979
      as(2) = 	10193.1217
      as(3) = 	-5742.9885
      as(4) = 	5858.6060
      as(5) = 	-3140.4730
      as(6) = 	536.9346
      as(7) = 	-143.0212
      alpha = 	8.8084
      beta = 	0.6807
      else if ((i.eq.5).or.(i.eq.6)) then
      ! O2 b 1Sig_g^+
      as(0) = 	30217.9494
      as(1) = 	-34209.9456
      as(2) = 	42484.4011
      as(3) = 	-34978.1369
      as(4) = 	25590.9050
      as(5) = 	-12584.9058
      as(6) = 	3591.1163
      as(7) = 	-765.4895
      alpha = 	6.9556
      beta = 	0.7365
      else if ((i.eq.13).or.(i.eq.14).or.(i.eq.15)) then
       ! mixed energy curve
     as(0) = 	15.7994
as(1) = 	-90.8425
as(2) = 	287.9272
as(3) = 	-1571.3064
as(4) = 	2314.1786
as(5) = 	2401.5303
as(6) = 	6816.2068
as(7) = 	14815.8125
alpha = 	0.2695
beta = 	1.6871
gam = 	13.9521
del =	27.7976 
      else if (i.eq.7) then
      ! O2 c 1Sig_u^-
      as(0) = 	-311583.8841
      as(1) = 	-272929.9302
      as(2) = 	554220.2010
      as(3) = 	1197507.5992
      as(4) = 	111308.5175
      as(5) = 	-1563881.9297
      as(6) = 	-1064389.9976
      as(7) = 	1355645.1238
      alpha = 	1.5690
      beta = 	1.0261
      else if (i.eq.16) then
       ! mixed energy curve 3 Del_g- + 1S
      as(0) = 	-1049657.501
        as(1) = 	9416957.826
        as(2) = 	-35160894.38
        as(3) = 	72461031.14
        as(4) = 	-90433021.03
        as(5) = 	69219798.22
        as(6) = 	-30426960.63
        as(7) = 	5999459.497
        alpha = 	2.0466
        beta = 	1.1382
        gam = 	-32.5392
        del =	21.3867
      else if ((i.eq.8).or.(i.eq.9).or.(i.eq.10)) then
      ! O2 C 3Del_u
      as(0) = 	7133519.1248
        as(1) = 	-21842782.2951
        as(2) = 	18821411.2536
        as(3) = 	4796852.3950
        as(4) = 	-12377676.7323
        as(5) = 	-343577.2019
        as(6) = 	5875440.3400
        as(7) = 	-2047566.0842
        alpha = 	3.3916
        beta = 	0.9413
      else if ((i.eq.11).or.(i.eq.12)) then
      ! O2 A 3Sig_u^+
       alpha =  0.1044
       beta =   5.4643
       as(0) =  0.0105
       as(1) =  -75.2131
       as(2) =  5884.3053
       as(3) =  241893.1847
       as(4) =  6995.4774
       as(5) =  -2620.5113
       as(6) =  -14514.4843
       as(7) =  -10838.5723
      endif
    
          do k=0,7
            v(i)= v(i) + as(k)*dexp(-alpha*beta**k*r**2)
          enddo
          if ((i.eq.13).or.(i.eq.14).or.(i.eq.15).or.(i.eq.16)) then
            v(i)= v(i) + gam*dexp(-del*(r-1.7d0)**2)
          endif
    
    ! Compute the gradient if needed
          if (igrad.eq.1) then
           do k=0,7
            grad(i)=grad(i)-2.d0*as(k)*alpha*beta**k*r*dexp(-alpha*beta**k*r**2)
           enddo
          if ((i.eq.13).or.(i.eq.14).or.(i.eq.15).or.(i.eq.16)) then
            grad(i)=grad(i)-2.0d0*del*gam*(r-1.7d0)*dexp(-del*(r-1.7d0)**2)
           endif
          endif
    
          enddo
    
          return
          end subroutine ev2gm2
    


